vector<vector<int>> merge(vector<vector<int>> iv) {
    sort(iv.begin(), iv.end());
    vector<vector<int>> out;
    for (auto& cur : iv) {
        if (!out.empty() && cur[0] <= out.back()[1])
            out.back()[1] = cur[1];
        else
            out.push_back(cur);
    }
    return out;
}

