vector<vector<int>> insert(const vector<vector<int>>& iv, vector<int> nw) {
    vector<vector<int>> out;
    size_t i = 0, n = iv.size();
    // 1. intervals entirely before nw
    while (i < n && iv[i][1] < nw[0]) out.push_back(iv[i++]);
    // 2. intervals overlapping nw: absorb
    while (i < n && iv[i][0] <= nw[1]) {
        nw[0] = min(nw[0], iv[i][0]);
        nw[1] = max(nw[1], iv[i][1]);
        ++i;
    }
    out.push_back(nw);
    // 3. intervals entirely after nw
    while (i < n) out.push_back(iv[i++]);
    return out;
}

